32	export class TimelineService {
33	  public static sendMessage = async (
34	    roomId: string,
35	    message: string,
36	    mentions?: Mentions,
37	    htmlBody?: string,
38	  ) => {
39	    const room = MatrixCore.getRoom(roomId);
40	    const timeline = await room.timeline();
41	    if (!timeline) throw new Error("Timeline not found");
42	    let messageContent = htmlBody
43	      ? messageEventContentFromHtml(message, htmlBody)
44	      : messageEventContentFromMarkdown(message);
45	    if (mentions) messageContent = messageContent.withMentions(mentions);
46	    await timeline.send(messageContent);
47	  };
