113	  public static forwardMessage = async (
114	    roomId: string,
115	    event: EventTimelineItem,
116	    messageType: ForwardMessageType,
117	  ) => {
118	    const client = MatrixCore.getClient();
119	    const room = MatrixCore.getRoom(roomId);
120	    const timeline = await room.timeline();
121	    if (!timeline) throw new Error("Timeline not found");
122	
123	    if (messageType === "text") {
124	      const textContent = this.getTextContent(event);
125	      if (!textContent) throw new Error("Text content not found");
126	      await timeline.send(messageEventContentFromMarkdown(textContent));
127	      return;
128	    }
129	
130	    if (messageType === "image") {
131	      const imageContent = this.getImageContent(event);
132	      if (!imageContent) throw new Error("Image content not found");
133	
134	      const mediaFile = await client.getMediaFile(
135	        imageContent.source,
136	        imageContent.filename,
137	        imageContent.info?.mimetype || "image/jpeg",
138	        true,
139	        undefined,
140	      );
141	      const filePath = mediaFile.path();
142	      const fileSource: UploadParameters = {
143	        source: new UploadSource.File({ filename: filePath }),
144	        caption: imageContent.caption || undefined,
145	        formattedCaption: undefined,
146	        mentions: undefined,
147	        inReplyTo: undefined,
148	      };
149	      const imageHandle = timeline.sendImage(
150	        fileSource,
151	        new UploadSource.File({ filename: filePath }),
152	        {
153	          height: imageContent.info?.height || BigInt(0),
154	          width: imageContent.info?.width || BigInt(0),
155	          mimetype: imageContent.info?.mimetype || "image/jpeg",
156	          size: imageContent.info?.size || BigInt(0),
157	          thumbnailInfo: imageContent.info?.thumbnailInfo,
158	          thumbnailSource: undefined,
159	          blurhash: imageContent.info?.blurhash || "",
160	          isAnimated: false,
161	        },
162	      );
163	      await imageHandle.join();
164	      return;
165	    }
166	
167	    if (messageType === "video") {
168	      const videoContent = this.getVideoContent(event);
169	      if (!videoContent) throw new Error("Video content not found");
170	
171	      const mediaFile = await client.getMediaFile(
172	        videoContent.source,
173	        videoContent.filename,
174	        videoContent.info?.mimetype || "video/mp4",
175	        true,
176	        undefined,
177	      );
178	      const filePath = mediaFile.path();
179	      const fileSource: UploadParameters = {
180	        source: new UploadSource.File({ filename: filePath }),
181	        caption: videoContent.caption || undefined,
182	        formattedCaption: undefined,
183	        mentions: undefined,
184	        inReplyTo: undefined,
185	      };
186	      const videoHandle = timeline.sendVideo(
187	        fileSource,
188	        new UploadSource.File({ filename: filePath }),
189	        {
190	          height: videoContent.info?.height || BigInt(0),
191	          width: videoContent.info?.width || BigInt(0),
192	          mimetype: videoContent.info?.mimetype || "video/mp4",
193	          size: videoContent.info?.size || BigInt(0),
194	          duration: videoContent.info?.duration || 0,
195	          thumbnailInfo: videoContent.info?.thumbnailInfo,
196	          thumbnailSource: undefined,
197	          blurhash: videoContent.info?.blurhash || "",
198	        },
199	      );
200	      await videoHandle.join();
201	      return;
202	    }
203	
204	    if (messageType === "audio") {
205	      const audioContent = this.getAudioContent(event);
206	      if (!audioContent) throw new Error("Audio content not found");
207	
208	      const mediaFile = await client.getMediaFile(
209	        audioContent.source,
210	        audioContent.filename,
211	        audioContent.info?.mimetype || "audio/mpeg",
212	        true,
213	        undefined,
214	      );
215	      const filePath = mediaFile.path();
216	      const fileSource: UploadParameters = {
217	        source: new UploadSource.File({ filename: filePath }),
218	        caption: undefined,
219	        formattedCaption: undefined,
220	        mentions: undefined,
221	        inReplyTo: undefined,
222	      };
223	      const audioHandle = timeline.sendAudio(fileSource, {
224	        mimetype: audioContent.info?.mimetype || "audio/mpeg",
225	        size: audioContent.info?.size || BigInt(0),
226	        duration: audioContent.info?.duration || 0,
227	      });
228	      await audioHandle.join();
229	      return;
230	    }
231	
232	    if (messageType === "file") {
233	      const fileContent = this.getFileContent(event);
234	      if (!fileContent) throw new Error("File content not found");
235	
236	      const mediaFile = await client.getMediaFile(
237	        fileContent.source,
238	        fileContent.filename,
239	        fileContent.info?.mimetype || "application/octet-stream",
240	        true,
241	        undefined,
242	      );
243	      const filePath = mediaFile.path();
244	      const fileHandle = timeline.sendFile(
245	        {
246	          source: new UploadSource.File({ filename: filePath }),
247	          caption: undefined,
248	          formattedCaption: undefined,
249	          mentions: undefined,
250	          inReplyTo: undefined,
251	        },
252	        {
253	          size: fileContent.info?.size || BigInt(0),
254	          mimetype: fileContent.info?.mimetype || "application/octet-stream",
255	          thumbnailInfo: undefined,
256	          thumbnailSource: undefined,
257	        },
258	      );
259	      await fileHandle.join();
260	      return;
261	    }
262	
263	    throw new Error(`Unsupported message type: ${messageType}`);
264	  };
