293	  public static sendMedia = async (
294	    roomId: string,
295	    asset: Asset,
296	    caption?: string,
297	  ) => {
298	    if (!asset?.uri) throw new Error("No uri found");
299	    const room = MatrixCore.getRoom(roomId);
300	    const timeline = await room.timeline();
301	    if (!timeline) throw new Error("Timeline not found");
302	
303	    const type = asset.type ?? "image/jpeg";
304	    const assetWidth = asset.width ?? 0;
305	    const assetHeight = asset.height ?? 0;
306	    const isVideo = type.startsWith("video/");
307	
308	    const fileSource: UploadParameters = {
309	      source: new UploadSource.File({
310	        filename: decodeURIComponent(asset.uri.replace("file://", "")),
311	      }),
312	      caption: caption || undefined,
313	      formattedCaption: undefined,
314	      mentions: undefined,
315	      inReplyTo: undefined,
316	    };
317	
318	    if (isVideo) {
319	      const videoHandle = timeline.sendVideo(
320	        fileSource,
321	        new UploadSource.File({
322	          filename: decodeURIComponent(asset.uri.replace("file://", "")),
323	        }),
324	        {
325	          height: BigInt(assetHeight),
326	          width: BigInt(assetWidth),
327	          mimetype: type,
328	          size: BigInt(asset.fileSize ?? 0),
329	          duration: asset.duration ? Math.round(asset.duration * 1000) : 0,
330	          thumbnailInfo: {
331	            height: BigInt(assetHeight),
332	            width: BigInt(assetWidth),
333	            mimetype: type,
334	            size: BigInt(asset.fileSize ?? 0),
335	          },
336	          thumbnailSource: undefined,
337	          blurhash: "",
338	        },
339	      );
340	      await videoHandle.join();
341	    } else {
342	      const imageHandle = timeline.sendImage(
343	        fileSource,
344	        new UploadSource.File({
345	          filename: decodeURIComponent(asset.uri.replace("file://", "")),
346	        }),
347	        {
348	          height: BigInt(assetHeight),
349	          width: BigInt(assetWidth),
350	          mimetype: type,
351	          size: BigInt(asset.fileSize ?? 0),
352	          thumbnailInfo: {
353	            height: BigInt(assetHeight),
354	            width: BigInt(assetWidth),
355	            mimetype: type,
356	            size: BigInt(asset.fileSize ?? 0),
357	          },
358	          thumbnailSource: undefined,
359	          blurhash: "",
360	          isAnimated: false,
361	        },
362	      );
363	      await imageHandle.join();
364	    }
365	  };
