515	  public static getTopReactions = (
516	    event: EventTimelineItem,
517	    limit = 3,
518	  ): TimelineReaction[] => {
519	    const normalized = this.getNormalizedReactions(event);
520	    return normalized
521	      .sort(
522	        (a, b) => b.count - a.count || b.latestTimestamp - a.latestTimestamp,
523	      )
524	      .slice(0, limit);
525	  };
526	
527	  private static getNormalizedReactions = (
528	    event: EventTimelineItem,
529	  ): TimelineReaction[] => {
530	    const reactionCandidates: unknown[] = [
531	      this.readValue(event, ["reactions"]),
532	      this.readValue(event, ["properties", "reactions"]),
533	      this.readValue(event, ["content", "inner", "reactions"]),
534	      this.readValue(event, ["content", "inner", "content", "reactions"]),
535	      this.readValue(event, [
536	        "content",
537	        "inner",
538	        "content",
539	        "kind",
540	        "inner",
541	        "content",
542	        "reactions",
543	      ]),
544	    ].filter(Boolean);
545	
546	    for (const candidate of reactionCandidates) {
547	      const parsed = this.parseReactionsCandidate(candidate);
548	      if (parsed.length) return parsed;
549	    }
550	
551	    return [];
552	  };
553	
554	  private static parseReactionsCandidate = (
555	    candidate: unknown,
556	  ): TimelineReaction[] => {
557	    if (!candidate) return [];
558	
559	    if (Array.isArray(candidate)) {
560	      return candidate
561	        .map((reaction) => this.parseSingleReaction(reaction))
562	        .filter((reaction): reaction is TimelineReaction => Boolean(reaction));
563	    }
564	
565	    if (candidate instanceof Map) {
566	      return Array.from(candidate.entries())
567	        .map(([key, value]) => this.parseEntryReaction(key, value))
568	        .filter((reaction): reaction is TimelineReaction => Boolean(reaction));
569	    }
570	
571	    if (typeof candidate === "object") {
572	      return Object.entries(candidate as Record<string, unknown>)
573	        .map(([key, value]) => this.parseEntryReaction(key, value))
574	        .filter((reaction): reaction is TimelineReaction => Boolean(reaction));
575	    }
576	
577	    return [];
578	  };
579	
580	  private static parseEntryReaction = (
581	    key: string,
582	    rawValue: unknown,
583	  ): TimelineReaction | null => {
584	    const currentUserId = MatrixCore.instance?.userId() ?? "";
585	    const normalizedKey = this.normalizeReactionKey(key);
586	    if (!normalizedKey) return null;
587	
588	    const detailedReaction = this.parseSingleReaction(rawValue);
589	    if (detailedReaction) {
590	      return {
591	        ...detailedReaction,
592	        key: normalizedKey,
593	        displayKey: String(detailedReaction.displayKey || normalizedKey).slice(
594	          0,
595	          16,
596	        ),
597	      };
598	    }
599	
600	    const senders = this.toSenders(rawValue, currentUserId);
601	    return {
602	      key: normalizedKey,
603	      displayKey: normalizedKey.slice(0, 16),
604	      count: senders.count,
605	      latestTimestamp: senders.latestTimestamp,
606	      isHighlighted: senders.isHighlighted,
607	    };
608	  };
609	
610	  private static parseSingleReaction = (
611	    rawReaction: unknown,
612	  ): TimelineReaction | null => {
613	    if (!rawReaction || typeof rawReaction !== "object") return null;
614	    const currentUserId = MatrixCore.instance?.userId() ?? "";
615	
616	    const reaction = rawReaction as Record<string, unknown>;
617	    const normalizedKey = this.normalizeReactionKey(
618	      reaction.key ??
619	        reaction.displayKey ??
620	        reaction.emoji ??
621	        reaction.reaction,
622	    );
623	    if (!normalizedKey) return null;
624	
625	    const senders = this.toSenders(reaction.senders, currentUserId);
626	    const rawCount = Number(reaction.count);
627	    const count =
628	      Number.isFinite(rawCount) && rawCount > 0 ? rawCount : senders.count;
629	
630	    return {
631	      key: normalizedKey,
632	      displayKey: String(reaction.displayKey ?? normalizedKey).slice(0, 16),
633	      count,
634	      latestTimestamp: senders.latestTimestamp,
635	      isHighlighted:
636	        Boolean(reaction.isHighlighted) ||
637	        Boolean(reaction.highlighted) ||
638	        senders.isHighlighted,
639	    };
640	  };
641	
642	  private static toSenders = (
643	    rawSenders: unknown,
644	    currentUserId: string,
645	  ): { count: number; latestTimestamp: number; isHighlighted: boolean } => {
646	    if (!rawSenders)
647	      return { count: 1, latestTimestamp: 0, isHighlighted: false };
648	
649	    if (Array.isArray(rawSenders)) {
650	      const timestamps = rawSenders
651	        .map((sender) => this.extractTimestamp(sender))
652	        .filter((timestamp) => timestamp > 0);
653	      const isHighlighted = rawSenders.some(
654	        (sender) => this.extractSenderUserId(sender) === currentUserId,
655	      );
656	      return {
657	        count: rawSenders.length || 1,
658	        latestTimestamp: timestamps[0] ?? 0,
659	        isHighlighted,
660	      };
661	    }
662	
663	    if (rawSenders instanceof Map) {
664	      const entries = Array.from(rawSenders.entries());
665	      const values = entries.map(([, sender]) => sender);
666	      const timestamps = values
667	        .map((sender) => this.extractTimestamp(sender))
668	        .filter((timestamp) => timestamp > 0);
669	      const isHighlighted = entries.some(([senderId, sender]) => {
670	        if (typeof senderId === "string" && senderId === currentUserId)
671	          return true;
672	        return this.extractSenderUserId(sender) === currentUserId;
673	      });
674	      return {
675	        count: values.length || 1,
676	        latestTimestamp: timestamps[0] ?? 0,
677	        isHighlighted,
678	      };
679	    }
680	
681	    if (typeof rawSenders === "object") {
682	      const entries = Object.entries(rawSenders as Record<string, unknown>);
